   if X[2]>.035:p.append([*X,u,v,*rgb])
a=np.array(p);print('n',len(a),'xyz bounds',a[:,:3].min(0),a[:,:3].max(0),'mean',a[:,:3].mean(0),'median',np.median(a[:,:3],axis=0));print('pixel bounds',a[:,3:5].min(0),a[:,3:5].max(0))
# group high-contrast geometric positions
for thr in [0.04,.045,.048]:
 b=a[a[:,2]>thr];print('z>',thr,len(b),b[:,:3].mean(0))
